Further to my comment above, I wondered if log10 was too slow, so I wrote a version that doesn't use it. For four digit numbers this version is about 35% quicker, falling to about 16% quicker for ten digit numbers. One disadvantage is that it requires space for the full ten digits in the buffer. I don't swear it doesn't have any bugs!

public static int ToCharArray2(uint value, char[] buffer, int bufferIndex)
{
    const int maxLength = 10;

    if (value == 0)
    {
        buffer[bufferIndex] = '0';
        return 1;
    }

    int startIndex = bufferIndex + maxLength - 1;
    int index = startIndex;
    do
    {
        buffer[index] = (char)('0' + value % 10);
        value /= 10;
        --index;
    }
    while (value != 0);

    int length = startIndex - index;

    if (bufferIndex != index + 1)
    {
        while (index != startIndex)
        {
            ++index;
            buffer[bufferIndex] = buffer[index];
            ++bufferIndex;
        }
    }

    return length;
}

